#pragma once

#include <stdint.h>

// AI: below section was generated by an AI
// Pair two existing SK6812 addresses without changing their wire protocol.
// Channel numbers refer to the old RGBW sliders, before color-order conversion.
namespace PairedRgbw {
  constexpr uint8_t WARM_CHANNEL = 1; // green
  constexpr uint8_t COLD_CHANNEL = 2; // blue
  constexpr unsigned ADDRESSES_PER_PIXEL = 2;
  constexpr unsigned BYTES_PER_PIXEL = 8;
  constexpr uint8_t COLOR_ONLY = 0;
  constexpr uint8_t WHITE_ONLY = 1;
  constexpr uint8_t COLOR_WHITE = 2;
  constexpr uint8_t UNFILTERED = 255; // pixels belonging to ordinary output types

  constexpr bool validMode(int mode) { return mode >= COLOR_ONLY && mode <= COLOR_WHITE; }

  // Keep effect buffers intact. Convert only the rendered output: explicit W
  // wins, otherwise animations derive white brightness from their RGB pixels.
  inline uint32_t segmentColor(uint32_t color, uint8_t mode, bool animated) {
    if (mode == COLOR_ONLY) return color & 0x00FFFFFFU;
    unsigned white = color >> 24;
    if (animated && white == 0) {
      const unsigned r = (color >> 16) & 255, g = (color >> 8) & 255, b = color & 255;
      white = r > g ? (r > b ? r : b) : (g > b ? g : b);
    }
    return (mode == WHITE_ONLY ? 0U : color & 0x00FFFFFFU) | (white << 24);
  }

  constexpr uint8_t capabilities(uint8_t available, uint8_t mode) {
    return mode == COLOR_ONLY ? available & ~uint8_t(0x06) : mode == WHITE_ONLY ? (available & ~uint8_t(0x01)) | uint8_t(0x02) : available;
  }

  constexpr bool validChannels(int warm, int cold) {
    return warm >= 0 && warm < 4 && cold >= 0 && cold < 4 && warm != cold;
  }

  constexpr unsigned physicalCount(unsigned count, unsigned skip) {
    return (count + skip) * ADDRESSES_PER_PIXEL;
  }

  constexpr unsigned physicalIndex(unsigned pix, unsigned count, unsigned skip, bool reversed) {
    return ((reversed ? count - pix - 1 : pix) + skip) * ADDRESSES_PER_PIXEL;
  }

  constexpr unsigned channelShift(uint8_t channel) {
    return channel == 0 ? 16 : channel == 1 ? 8 : channel == 2 ? 0 : 24;
  }

  // Unused channels are always zero, including when white brightness is zero.
  constexpr uint32_t whiteColor(uint8_t warm, uint8_t cold, uint8_t warmChannel, uint8_t coldChannel) {
    return (uint32_t(warm) << channelShift(warmChannel)) | (uint32_t(cold) << channelShift(coldChannel));
  }

  struct Output {
    uint32_t rgb;
    uint32_t white;
  };

  // White is removed from the RGB address and routed only to the second address.
  constexpr Output split(uint32_t color, uint16_t warmCold, uint8_t warmChannel, uint8_t coldChannel) {
    return {color & 0x00FFFFFFU, whiteColor(warmCold & 0xFF, warmCold >> 8, warmChannel, coldChannel)};
  }
}
